var elements = document.getElementsByClassName("navbar");
for (var i = 0; i < elements.length; i++) {
  elements[i].style.backgroundColor = "#191945";
  var brandElements = elements[i].getElementsByClassName("navbar-brand");
  for (var j = 0; j < brandElements.length; j++) {
    brandElements[j].style.color = "white";
  }
  var itemElements = elements[i].getElementsByClassName("nav-link btn-login-area");
  for (var k = 0; k < itemElements.length; k++) {
    itemElements[k].style.color = "white";
  }
}

